def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    count = 3

    if count == 0:
        return None

    total = v1 + v2 + v3
    average = total / count

    return {
        "value": average,
        "trace": {
            "values": [v1, v2, v3],
            "total": total,
            "count": count,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage of net revenues"
            }
        }
    }
